1	use callisto_model::{CommandRunner, ComposePrBodyReport, SCHEMA_VERSION};
2	
3	use crate::commands::version::plan_version;
4	use crate::error::GraphError;
5	use crate::infer::SeverityInference;
6	use crate::resolver::DependencyResolver;
7	use crate::Workspace;
8	
9	#[derive(Clone, Debug, Default)]
10	pub struct PrBodyOptions {
11	    pub existing_body: Option<String>,
12	    pub labels: Vec<String>,
13	    pub branch: Option<String>,
14	}
15	
16	pub fn compose_pr_body<R: CommandRunner, D: DependencyResolver, I: SeverityInference>(
17	    ws: &Workspace<'_, R, D>,
18	    inference: &I,
19	    opts: &PrBodyOptions,
20	) -> Result<ComposePrBodyReport, GraphError> {
21	    let plan = plan_version(ws, inference, &crate::commands::version::VersionOptions::default())?;
22	    render_pr_body_from_plan(&plan, opts)
23	}
24	
25	pub fn render_pr_body_from_plan(
26	    plan: &crate::plan::VersionPlan,
27	    opts: &PrBodyOptions,
28	) -> Result<ComposePrBodyReport, GraphError> {
29	    let mut body = String::new();
30	
31	    // Preserve custom user notes above ## Release Preview if an existing body was passed
32	    if let Some(ref existing) = opts.existing_body {
33	        if let Some((prefix, _)) = existing.split_once("## Release Preview") {
34	            if !prefix.trim().is_empty() {
35	                body.push_str(prefix);
36	                if !prefix.ends_with('\n') {
37	                    body.push('\n');
38	                }
39	            }
40	        }
41	    }
42	
43	    body.push_str("## Release Preview\n\n");
44	    body.push_str("This automated PR was generated by [Callisto](https://github.com/orin-dx/callisto). Merging this PR will publish the updated packages to their release targets.\n\n");
45	
46	    if !opts.labels.is_empty() {
47	        body.push_str(&format!("**Suggested PR Labels**: `{}`\n\n", opts.labels.join("`, `")));
48	    }
49	
50	    if plan.bumps.is_empty() {
51	        body.push_str("> [!NOTE]\n");
52	        body.push_str("> **No pending changesets found.** Workspace packages are currently up to date.\n\n");
53	        let branch = opts.branch.as_deref().unwrap_or("callisto/version-packages");
54	        body.push_str("<details>\n<summary><b>Release Workflow Instructions</b></summary>\n\n");
55	        body.push_str("- **Merging this PR**: Merging into `main` will automatically publish all updated packages to their release registries.\n");
56	        body.push_str("- **Adding more changesets**: If additional changesets are pushed to `main`, Callisto will automatically re-calculate and update this PR.\n");
57	        body.push_str(&format!(
58	            "- **Manual edits**: You can make manual adjustments directly on the `{}` branch if needed.\n\n",
59	            branch
60	        ));
61	        body.push_str("</details>\n");
62	        return Ok(ComposePrBodyReport {
63	            schema_version: SCHEMA_VERSION,
64	            body,
65	            diagnostics: Vec::new(),
66	        });
67	    }
68	
69	    // 1. Executive Summary Table
70	    body.push_str("### 📊 Release Summary\n\n");
71	    body.push_str("| Package | Ecosystem | Current | Target | Bump | Reason |\n");
72	    body.push_str("| :--- | :--- | :--- | :--- | :--- | :--- |\n");
73	
74	    let mut has_major = false;
75	
76	    for bump in &plan.bumps {
77	        if bump.severity == callisto_model::Severity::Major {
78	            has_major = true;
79	        }
80	
81	        let eco = bump.package.ecosystem().map(|e| e.prefix()).unwrap_or("core");
82	
83	        let reason_str = match &bump.reason {
84	            Some(callisto_model::BumpReason::Changeset { changesets }) => {
85	                format!("Changeset (`{}`)", changesets.join("`, `"))
86	            }
87	            Some(callisto_model::BumpReason::Cascade { via, .. }) => {
88	                format!("Cascade from `{}`", via.display_name())
89	            }
90	            Some(callisto_model::BumpReason::PeerEscalation { via, .. }) => {
91	                format!("Peer escalation from `{}`", via.display_name())
92	            }
93	            Some(callisto_model::BumpReason::FixedGroupUnion { group }) => {
94	                format!("Fixed group `{}`", group.as_str())
95	            }
96	            Some(callisto_model::BumpReason::LinkedGroupUnion { group }) => {
97	                format!("Linked group `{}`", group.as_str())
98	            }
99	            Some(callisto_model::BumpReason::Inference { commits, .. }) => {
100	                format!("Inferred ({commits} commits)")
101	            }
102	            Some(callisto_model::BumpReason::PreRelease { tag }) => {
103	                format!("Prerelease (`{tag}`)")
104	            }
105	            Some(callisto_model::BumpReason::NewGroupMember { group }) => {
106	                format!("New member (`{}`)", group.as_str())
107	            }
108	            _ => "Package bump".to_string(),
109	        };
110	
111	        body.push_str(&format!(
112	            "| `{}` | `{}` | `{}` | **`{}`** | `{}` | {} |\n",
113	            bump.package.display_name(),
114	            eco,
115	            bump.from.render(),
116	            bump.to.render(),
117	            bump.severity,
118	            reason_str
119	        ));
120	    }
121	
122	    body.push('\n');
123	
124	    // 2. Alert Callouts
125	    if has_major {
126	        body.push_str("> [!IMPORTANT]\n");
127	        body.push_str("> **Major Version Bumps Detected**: This release contains major breaking changes. Review full changelogs below before merging.\n\n");
128	    } else {
129	        body.push_str("> [!NOTE]\n");
130	        body.push_str(&format!(
131	            "> **{} package(s)** queued for versioning. All changes are backward compatible.\n\n",
132	            plan.bumps.len()
133	        ));
134	    }
135	
136	    // 3. Collapsible Package Details
137	    body.push_str("### 📦 Package Release Details\n\n");
138	
139	    for bump in &plan.bumps {
140	        let is_open =
141	            bump.severity == callisto_model::Severity::Major || bump.severity == callisto_model::Severity::Minor;
142	        let open_attr = if is_open { " open" } else { "" };
143	
144	        body.push_str(&format!(
145	            "<details{}>\n<summary><b>{}</b> <code>{}</code> → <code>{}</code> ({})</summary>\n\n",
146	            open_attr,
147	            bump.package.display_name(),
148	            bump.from.render(),
149	            bump.to.render(),
150	            bump.severity
151	        ));
152	
153	        body.push_str(&format!(
154	            "#### Version Change\n`{}` ➔ `{}`\n\n",
155	            bump.from.render(),
156	            bump.to.render()
157	        ));
158	
159	        let matching_write = plan.changelog_writes.iter().find(|w| w.input.package == bump.package);
160	
161	        let mut rendered = false;
162	        if let Some(w) = matching_write {
163	            if let Ok(section) = callisto_changelog::render_section(&w.input) {
164	                body.push_str("#### Release Reason\n");
165	                body.push_str(&section);
166	                body.push('\n');
167	                rendered = true;
168	            }
169	        }
170	
171	        if !rendered {
172	            body.push_str("#### Release Reason\n");
173	            match &bump.reason {
174	                Some(reason) => match reason {
175	                    callisto_model::BumpReason::Changeset { changesets } => {
176	                        body.push_str(&format!("- Associated changesets: `{}`\n\n", changesets.join("`, `")));
177	                    }
178	                    callisto_model::BumpReason::Cascade {
179	                        via,
180	                        spec,
181	                        dependency_to,
182	                        ..
183	                    } => {
184	                        body.push_str(&format!(
185	                            "- Automatic dependency cascade triggered by `{}` (spec `{}` target `{}`).\n\n",
186	                            via.display_name(),
187	                            spec,
188	                            dependency_to.render()
189	                        ));
190	                    }
191	                    callisto_model::BumpReason::PeerEscalation { via, spec } => {
192	                        body.push_str(&format!(
193	                            "- Peer dependency escalation triggered by `{}` (spec `{}`).\n\n",
194	                            via.display_name(),
195	                            spec
196	                        ));
197	                    }
198	                    callisto_model::BumpReason::FixedGroupUnion { group } => {
199	                        body.push_str(&format!(
200	                            "- Fixed group synchronization for group `{}`.\n\n",
201	                            group.as_str()
202	                        ));
203	                    }
204	                    callisto_model::BumpReason::LinkedGroupUnion { group } => {
205	                        body.push_str(&format!(
206	                            "- Linked group version alignment for group `{}`.\n\n",
207	                            group.as_str()
208	                        ));
209	                    }
210	                    callisto_model::BumpReason::Inference { commits, .. } => {
211	                        body.push_str(&format!(
212	                            "- Inferred from {commits} commit(s) since the last release.\n\n"
213	                        ));
214	                    }
215	                    callisto_model::BumpReason::PreRelease { tag } => {
216	                        body.push_str(&format!("- Pre-release finalization (tag `{tag}`).\n\n"));
217	                    }
218	                    callisto_model::BumpReason::NewGroupMember { group } => {
219	                        body.push_str(&format!("- New member of group `{}`.\n\n", group.as_str()));
220	                    }
221	                    _ => {}
222	                },
223	                None => {
224	                    body.push_str("_No changelog entries available._\n\n");
225	                }
226	            }
227	        }
228	
229	        body.push_str("</details>\n\n");
230	    }
231	
232	    // 4. Instructions Footer
233	    let branch = opts.branch.as_deref().unwrap_or("callisto/version-packages");
234	    body.push_str("<details>\n<summary><b>Release Workflow Instructions</b></summary>\n\n");
235	    body.push_str("- **Merging this PR**: Merging into `main` will automatically publish all updated packages to their release registries.\n");
236	    body.push_str("- **Adding more changesets**: If additional changesets are pushed to `main`, Callisto will automatically re-calculate and update this PR.\n");
237	    body.push_str(&format!(
238	        "- **Manual edits**: You can make manual adjustments directly on the `{}` branch if needed.\n\n",
239	        branch
240	    ));
241	    body.push_str("</details>\n");
242	
243	    Ok(ComposePrBodyReport {
244	        schema_version: SCHEMA_VERSION,
245	        body,
246	        diagnostics: Vec::new(),
247	    })
248	}
